-- Run this whole file as ONE query (one transaction). It creates the table and the functions, adds six test chunks,
-- checks the search, and always ends in  raise exception 'RESULT: PASS ...'  (or FAIL), so nothing is kept: no table,
-- no function, no rows. It needs nothing that is not on the server already. If 01 has already been applied it still
-- runs: it re-creates the functions, sets the real rows aside and adds its six rows, all inside the same rolled-back
-- transaction, so the real rows are back, untouched, when it ends.
begin;


-- guard: the earlier draft (library_arch_nov20/sql/PROPOSED_kb_shelf.sql) made a table of the same name without two of
-- the columns below. If that one is here, stop: run 03_undo_kb_shelf.sql (or drop the draft's table) first.
do $g$ begin
  if to_regclass('pb_ai.kb_shelf') is not null and not exists (select 1 from pg_catalog.pg_attribute a
       where a.attrelid = to_regclass('pb_ai.kb_shelf') and a.attname = 'tsv_t' and not a.attisdropped) then
    raise exception 'pb_ai.kb_shelf exists in the older draft shape: run 03_undo_kb_shelf.sql first, then this file';
  end if;
