drop function if exists public.pb_ai_kb_shelf_search(text[], text, integer, text[]);   -- the draft's search function, if it was ever made

create table if not exists pb_ai.kb_shelf (
  id       text primary key,
  chunk    jsonb not null,           -- the chunk exactly as lib_kb.py writes it (LIBRARY_RULES.md section 2)
  state    text   generated always as (upper(coalesce(chunk->>'state', 'US'))) stored,                         -- 'US', 'TX', 'KS,MO'
  states   text[] generated always as (string_to_array(upper(coalesce(chunk->>'state', 'US')), ',')) stored,   -- {US}, {TX}, {KS,MO}
  coll     text   generated always as (split_part(id, '-', 1)) stored,                                         -- dig, osha, sp, mutcd, tc, spec, ...
  tsv      tsvector generated always as (
             setweight(to_tsvector('english', coalesce(chunk->>'title', '')), 'A') ||
             setweight(to_tsvector('english', coalesce(chunk->>'topic', '')), 'B') ||
             setweight(to_tsvector('english', coalesce(chunk->>'text',  '')), 'D')) stored,
  tsv_t    tsvector generated always as (to_tsvector('english', coalesce(chunk->>'title', ''))) stored,        -- title only: the title boost
  added_at timestamptz not null default now(),
  constraint kb_shelf_shape check (chunk->>'id' = id and length(chunk->>'text') between 200 and 1800
                                   and length(coalesce(chunk->>'title', '')) between 1 and 160 and chunk ? 'source'
                                   and chunk->>'state' ~ '^(US|[A-Z]{2}(,[A-Z]{2}){0,3})$')
);
create index if not exists kb_shelf_tsv on pb_ai.kb_shelf using gin (tsv);
create index if not exists kb_shelf_states on pb_ai.kb_shelf using gin (states);
alter table pb_ai.kb_shelf enable row level security;      -- no policies: only the function below (and the table owner) reads it
revoke all on pb_ai.kb_shelf from public, anon, authenticated, service_role;

-- The excerpt handed to Ask: the whole text when it fits; else the run of whole sentences (at most p_chars) that holds
-- the most of the question's word groups, the earliest such run on a tie (chunks lead with the answer). Never cuts
-- inside a sentence unless one sentence alone is longer than p_chars.
create or replace function pb_ai.kb_shelf_excerpt(p_text text, p_groups tsquery[], p_chars integer)
 returns text language plpgsql immutable set search_path to '' as $function$
declare s text[]; h int[] := '{}'; n int; a int; b int; len int; got int; best int := -1; ba int := 1; bb int := 1; tv tsvector;
begin
  if p_text is null or length(p_text) <= p_chars then return p_text; end if;
  s := regexp_split_to_array(p_text, '(?<=[.;?!])\s+');
  n := array_length(s, 1);
  for a in 1..n loop
    tv := to_tsvector('english', s[a]);
    h := h || (select count(*)::int from unnest(p_groups) q where tv @@ q);
  end loop;
  for a in 1..n loop
    len := 0; got := 0; b := a - 1;
    while b < n and len + length(s[b + 1]) + (case when len > 0 then 1 else 0 end) <= p_chars loop
      b := b + 1; len := len + length(s[b]) + (case when len > 0 then 1 else 0 end); got := got + h[b];
    end loop;
    if b < a then b := a; got := h[a]; end if;        -- one sentence longer than the limit: it is cut below
    if got > best then best := got; ba := a; bb := b; end if;
  end loop;
  return left(array_to_string(s[ba:bb], ' '), p_chars);
end $function$;
revoke all on function pb_ai.kb_shelf_excerpt(text, tsquery[], integer) from public, anon, authenticated, service_role;

-- Search the shelf.
--   p_q       the question as typed (used only when p_terms is empty)
--   p_state   the job's state code ('TX') or null. A state's chunks come back only for that state; 'US' chunks always.
--             With no state: 'US' chunks only (one state's rule is never offered as "the" rule).
--   p_k       how many excerpts (1 to 8)
--   p_terms   the word groups Ask builds for document search (retrieval.ts queryGroups): one entry per typed word,
--             "word synonym synonym". Each group counts once however many of its words a chunk has.
--   p_coll    only these collections (id prefix: 'osha', 'mutcd', 'spec', ...), or null for all
--   p_chars   longest excerpt (200 to 1800). A longer chunk is cut to its best run of whole sentences; 'cut' says so.
--   p_weights how much each entry of p_terms matters (same length; Ask sends how rare the word is in its core library,
--             so "mandrel" counts for more than "pipe"). Empty: worked out here from how rare the group is on the shelf.
-- Ranking: websearch_to_tsquery per group (so nothing typed can break the query), ts_rank_cd over title (heaviest), topic
-- and text, times how much of the question the chunk covers (by weight), times a title boost (the share found in the
-- title), times a small boost for the job state's own chunk, times 0.8 for confidence "low". At most 2 per title.
-- Each row says how much of the question it covers ('cover', 0 to 1) and how much its title does ('title_cover'): Ask hands
-- an excerpt to the model only when those are high enough (shelf.ts).
-- Speed: ranking every row that has ANY of the words is what gets slow on a big shelf (common words match a third of
-- it). So the rows to rank are picked by the RAREST groups: groups are added, rarest first, while they bring in at most
-- 5,000 rows in all; when even the rarest group is commoner than that, a row must have the two rarest. Counting a
-- group's rows is an index-only step. Every picked row is checked against all the groups (cheap); the 400 that cover the
-- most of the question get the full ts_rank_cd ranking (the costly step).
create or replace function public.pb_ai_kb_shelf_search(p_q text, p_state text default null, p_k integer default 3,
    p_terms text[] default null, p_coll text[] default null, p_chars integer default 700, p_weights real[] default null)
 returns jsonb language plpgsql stable security definer set search_path to '' as $function$
declare
  v_st text := nullif(upper(btrim(coalesce(p_state, ''))), '');
  v_states text[];
  v_k int := least(greatest(coalesce(p_k, 3), 1), 8);
  v_chars int := least(greatest(coalesce(p_chars, 700), 200), 1800);
  v_own boolean := coalesce(array_length(p_terms, 1), 0) > 0;
  v_wok boolean := v_own and coalesce(array_length(p_weights, 1), 0) = coalesce(array_length(p_terms, 1), 0);
  v_src text[]; v_g tsquery[] := '{}'; v_w real[] := '{}'; v_df int[] := '{}'; v_ord int[]; v_all tsquery; v_drive tsquery;
  g tsquery; t text; i int; k int := 0; n int; v_sum int := 0; v_cap constant int := 5000; v_rows real; v_wsum real; v jsonb;
begin
  if v_st is not null and v_st !~ '^[A-Z]{2}$' then v_st := null; end if;
  v_states := case when v_st is null or v_st = 'US' then array['US'] else array['US', v_st] end;
  -- the groups: Ask's own (word + synonyms), else the typed words one by one
  v_src := case when v_own then p_terms[1:12] else (regexp_split_to_array(lower(left(coalesce(p_q, ''), 300)), '[^a-z0-9]+'))[1:24] end;
  if v_src is null then return jsonb_build_object('ok', true, 'rows', '[]'::jsonb, 'groups', 0); end if;
  foreach t in array v_src loop
    k := k + 1;
    -- letters and digits only, joined with "or": websearch_to_tsquery never raises, whatever is typed
    t := btrim(regexp_replace(lower(left(coalesce(t, ''), 200)), '[^a-z0-9]+', ' ', 'g'));
    continue when t = '' or length(to_tsvector('english', t)) = 0;     -- only stop words: skip (and no NOTICE in the log)
    g := websearch_to_tsquery('english', replace(t, ' ', ' or '));
    continue when g is null or numnode(g) = 0 or g = any (v_g);
    v_g := v_g || g;
    v_w := v_w || (case when v_wok then least(greatest(coalesce(p_weights[k], 1), 0.05), 100) else null end)::real;
    exit when array_length(v_g, 1) >= 12;
  end loop;
  n := coalesce(array_length(v_g, 1), 0);
  if n = 0 then return jsonb_build_object('ok', true, 'rows', '[]'::jsonb, 'groups', 0); end if;
  -- how common each group is (whole shelf; index only)
  for i in 1..n loop
    v_df := v_df || (select count(*)::int from pb_ai.kb_shelf s where s.tsv @@ v_g[i]);
    v_all := case when v_all is null then v_g[i] else v_all || v_g[i] end;
  end loop;
  if not v_wok then   -- no weights given: a rare group matters more than a common one
    select greatest(c.reltuples, 1) into v_rows from pg_catalog.pg_class c where c.oid = 'pb_ai.kb_shelf'::regclass;
    for i in 1..n loop v_w[i] := ln(1 + greatest(v_rows, v_df[i]) / (v_df[i] + 1)); end loop;
  end if;
  select sum(x) into v_wsum from unnest(v_w) x;
  select array_agg(x.i order by v_df[x.i], x.i) into v_ord from generate_series(1, n) x(i) where v_df[x.i] > 0;
  if v_ord is null then return jsonb_build_object('ok', true, 'rows', '[]'::jsonb, 'groups', n); end if;
  if v_df[v_ord[1]] > v_cap and array_length(v_ord, 1) >= 2 then
    v_drive := v_g[v_ord[1]] && v_g[v_ord[2]];
  else
    foreach i in array v_ord loop
      exit when v_drive is not null and v_sum + v_df[i] > v_cap;
      v_drive := case when v_drive is null then v_g[i] else v_drive || v_g[i] end;
      v_sum := v_sum + v_df[i];
    end loop;
  end if;

  with hit as materialized (
    select s.id, s.chunk, s.state, s.coll, s.tsv,
           (select coalesce(sum(v_w[q.i]), 0) from generate_subscripts(v_g, 1) q(i) where s.tsv   @@ v_g[q.i])::real / v_wsum as m,   -- share of the question this chunk covers
           (select coalesce(sum(v_w[q.i]), 0) from generate_subscripts(v_g, 1) q(i) where s.tsv_t @@ v_g[q.i])::real / v_wsum as mt   -- share found in its title
      from pb_ai.kb_shelf s
     where s.tsv @@ v_drive and s.states && v_states
       and (p_coll is null or s.coll = any (p_coll))
  ), pre as (   -- the costly part (ts_rank_cd) only for the 400 rows that cover the most of the question
    select * from hit order by m desc, mt desc, id limit 400
  ), scored as (
    select h.id, h.chunk, h.state, h.coll, h.m, h.mt,
           ts_rank_cd('{0.1, 0.2, 0.6, 1.0}', h.tsv, v_all, 32)
             * (0.25 + 0.75 * h.m)                                                -- covers more of the question
             * (1 + 0.6 * h.mt)                                                   -- title boost
             * (case when h.state <> 'US' then 1.25 else 1 end)                   -- the job state's own chunk first
             * (case h.chunk->>'confidence' when 'low' then 0.8 else 1 end) as score
      from pre h
  ), top as (select * from scored order by score desc, id limit 40),
  capped as (select t2.*, row_number() over (partition by lower(t2.chunk->>'title') order by t2.score desc, t2.id) as rn from top t2),
  best as (select * from capped where rn <= 2 order by score desc, id limit v_k)
  select jsonb_build_object('ok', true, 'groups', n, 'rows', coalesce(jsonb_agg(jsonb_build_object(
           'id', b.id, 'state', b.state, 'coll', b.coll, 'title', b.chunk->>'title', 'topic', b.chunk->>'topic',
           'text', x.txt, 'cut', length(b.chunk->>'text') > v_chars,
           'source', b.chunk->>'source', 'url', b.chunk->>'url', 'conf', b.chunk->>'confidence', 'kind', b.chunk->>'kind',
           'edition', b.chunk->>'edition', 'checked', b.chunk->>'checked',
           'cover', round(b.m::numeric, 2), 'title_cover', round(b.mt::numeric, 2), 'score', round(b.score::numeric, 4)) order by b.score desc, b.id), '[]'::jsonb))
    into v
    from best b
    cross join lateral (select pb_ai.kb_shelf_excerpt(b.chunk->>'text', v_g, v_chars) as txt) x;
  return v;
end $function$;
revoke all on function public.pb_ai_kb_shelf_search(text, text, integer, text[], text[], integer, real[]) from public, anon, authenticated;
grant execute on function public.pb_ai_kb_shelf_search(text, text, integer, text[], text[], integer, real[]) to service_role;


-- ---- the test: always ends in raise exception 'RESULT: ...', so the table, the functions and the rows above are all rolled back
do $t$
declare r jsonb; out text := ''; ok boolean := true; n int; x jsonb; t0 timestamptz; ms numeric;
  procedure_sig constant text := 'public.pb_ai_kb_shelf_search(text, text, integer, text[], text[], integer, real[])';
  long_tx constant text := 'Texas requires a protective system in a trench 5 feet deep or deeper under the federal excavation standard, which Texas follows. '
    || 'The competent person inspects the trench each day before work starts. Spoil piles are kept at least 2 feet back from the edge of the trench. '
    || 'A ladder or ramp is required in a trench 4 feet deep or deeper so that no worker is more than 25 feet from a way out. '
    || 'Water in the trench is controlled before anyone goes in. Shoring is installed from the top down and removed from the bottom up. '
    || 'A registered professional engineer designs the protective system for a trench deeper than 20 feet. '
    || 'Flaggers on a Texas road job follow the Texas MUTCD and use a STOP/SLOW paddle at least 24 inches wide when they control traffic at the work zone. '
    || 'Tabulated data for a trench shield is kept on the job site while the shield is in use and shown to an inspector who asks for it.';
  ck constant text := 'x';
begin
  -- if 01 is already applied and the shelf has rows: set them aside for the length of this test, so the checks below see
  -- only the six test chunks. Like everything else here this is undone by the rollback: no real row is lost or changed.
  select count(*) into n from pb_ai.kb_shelf; out := out || ' real_rows_set_aside=' || n;
  delete from pb_ai.kb_shelf;
  -- the insert path lib_kb.py's shelf SQL uses: (id, chunk), run twice, plus a supersede
  for n in 1..2 loop
    delete from pb_ai.kb_shelf s using jsonb_array_elements('[{"id":"tc-tx-zz-2","supersedes":"tc-tx-zz-old"}]'::jsonb) e
     where e->>'supersedes' is not null and s.id = e->>'supersedes' and s.id <> e->>'id';
    insert into pb_ai.kb_shelf (id, chunk)
    select e->>'id', e from jsonb_array_elements(jsonb_build_array(
      jsonb_build_object('id','tc-tx-zz-1','state','TX','tier','shelf','title','Texas flagger rules: training and the STOP/SLOW paddle','topic','Traffic control: flaggers','source','Texas MUTCD 2011 Revision 2, Section 6E.01','url','https://example.gov/tx','confidence','high','kind','summary',
        'text','Texas flaggers are trained before they flag traffic. The flagger uses a STOP/SLOW paddle at least 24 inches wide and stands on the shoulder where drivers can see the paddle from far enough away to stop. Flagger stations are lit at night.'),
      jsonb_build_object('id','tc-tx-zz-2','state','TX','tier','shelf','title','Texas trench rules: the long version','topic','Trench safety: protective systems','source','29 CFR 1926 Subpart P as followed in Texas','url','https://example.gov/tx2','confidence','high','kind','summary','text',long_tx),
      jsonb_build_object('id','tc-ok-zz-1','state','OK','tier','shelf','title','Oklahoma flagger rules: training and the STOP/SLOW paddle','topic','Traffic control: flaggers','source','Oklahoma DOT','url','https://example.gov/ok','confidence','high','kind','summary',
        'text','Oklahoma flaggers are trained before they flag traffic. The flagger uses a STOP/SLOW paddle at least 18 inches wide and stands on the shoulder where drivers can see the paddle from far enough away to stop. Flagger stations are lit at night.'),
      jsonb_build_object('id','mutcd-6d-zz-1','state','US','tier','shelf','title','Flagger STOP/SLOW paddle: size and when it is used','topic','Traffic control: flaggers','source','MUTCD 11th Edition, Section 6D.02','url','https://example.gov/us','confidence','high','kind','verbatim',
        'text','The STOP/SLOW paddle shall be the primary and preferred hand-signaling device because the paddle gives road users more positive guidance than red flags. The paddle shall have an octagonal shape on a rigid handle and shall be at least 18 inches wide with letters at least 6 inches high.'),
      jsonb_build_object('id','mutcd-6d-zz-2','state','US','tier','shelf','title','Flagger paddle notes, low confidence','topic','Traffic control: flaggers','source','not confirmed','url','https://example.gov/us2','confidence','low','kind','summary',
        'text','The STOP/SLOW paddle shall be the primary and preferred hand-signaling device because the paddle gives road users more positive guidance than red flags. The paddle shall have an octagonal shape on a rigid handle and shall be at least 18 inches wide with letters at least 6 inches high.'),
      jsonb_build_object('id','spec-kc-zz-1','state','KS,MO','tier','shelf','title','Kansas City metro pipe bedding: granular embedment under the pipe','topic','Specs: bedding','source','KC Metro APWA Section 2100','url','https://example.gov/kc','confidence','high','kind','summary',
        'text','Kansas City metro standard specifications require granular embedment under the pipe, at least 4 inches deep for pipe up to 24 inches and 6 inches deep for larger pipe, shaped to support the barrel of the pipe along its full length and compacted before the pipe is laid.')
    )) e
    on conflict (id) do update set chunk = excluded.chunk where pb_ai.kb_shelf.chunk is distinct from excluded.chunk;
  end loop;
  select count(*) into n from pb_ai.kb_shelf where id like '%-zz-%';
  out := out || ' rows=' || n; ok := ok and n = 6;
  select count(*) into n from pb_ai.kb_shelf where id = 'spec-kc-zz-1' and states = array['KS','MO'] and coll = 'spec' and state = 'KS,MO';
  ok := ok and n = 1;
  -- a chunk that breaks the shape is refused
  begin insert into pb_ai.kb_shelf (id, chunk) values ('bad-1', '{"id":"bad-1","state":"Texas","title":"t","source":"s","text":"short"}'); ok := false; out := out || ' shape=NOT_REFUSED';
  exception when check_violation then out := out || ' shape=refused'; end;

  -- 1 Texas job: Texas and federal chunks, never Oklahoma's; the Texas chunk first
  r := public.pb_ai_kb_shelf_search('How wide does the flagger paddle have to be?', 'TX', 3, array['wide width', 'flagger', 'paddle']);
  select count(*) into n from jsonb_array_elements(r->'rows') e where e->>'state' not in ('TX', 'US');
  out := out || ' tx=' || coalesce((select string_agg(e->>'id', ',') from jsonb_array_elements(r->'rows') e), 'none');
  ok := ok and n = 0 and r->'rows'->0->>'id' = 'tc-tx-zz-1' and jsonb_array_length(r->'rows') = 3 and (r->'rows'->0->>'cover')::numeric = 1;
  -- low confidence ranks under the same text with high confidence
  ok := ok and (select (e->>'score')::numeric from jsonb_array_elements(r->'rows') e where e->>'id' = 'mutcd-6d-zz-1')
            > coalesce((select (e->>'score')::numeric from jsonb_array_elements(r->'rows') e where e->>'id' = 'mutcd-6d-zz-2'), 0);
  -- 2 Oklahoma job: Oklahoma's, not Texas's
  r := public.pb_ai_kb_shelf_search('How wide does the flagger paddle have to be?', 'ok', 5, array['wide width', 'flagger', 'paddle']);
  select count(*) into n from jsonb_array_elements(r->'rows') e where e->>'state' = 'TX';
  ok := ok and n = 0 and r->'rows'->0->>'id' = 'tc-ok-zz-1'; out := out || ' ok_first=' || (r->'rows'->0->>'id');
  -- 3 no state known: federal only
  r := public.pb_ai_kb_shelf_search('How wide does the flagger paddle have to be?', null, 5, array['wide width', 'flagger', 'paddle']);
  select count(*) into n from jsonb_array_elements(r->'rows') e where e->>'state' <> 'US';
  ok := ok and n = 0 and jsonb_array_length(r->'rows') = 2; out := out || ' nostate=' || jsonb_array_length(r->'rows') || 'US';
  -- 4 a chunk for two states shows in both and nowhere else
  ok := ok and public.pb_ai_kb_shelf_search('bedding under the pipe', 'MO', 3)->'rows'->0->>'id' = 'spec-kc-zz-1'
           and public.pb_ai_kb_shelf_search('bedding under the pipe', 'KS', 3)->'rows'->0->>'id' = 'spec-kc-zz-1'
           and not exists (select 1 from jsonb_array_elements(public.pb_ai_kb_shelf_search('bedding under the pipe', 'TX', 3)->'rows') e where e->>'id' = 'spec-kc-zz-1');
  out := out || ' twostate=ok';
  -- 5 title boost: same words, the chunk whose TITLE is about it wins over the one that only mentions it in the text
  r := public.pb_ai_kb_shelf_search('flagger paddle', 'TX', 5, array['flagger', 'paddle']);
  ok := ok and r->'rows'->0->>'id' = 'tc-tx-zz-1' and (r->'rows'->0->>'title_cover')::numeric = 1
           and (select (e->>'title_cover')::numeric from jsonb_array_elements(r->'rows') e where e->>'id' = 'tc-tx-zz-2') = 0;
  out := out || ' title_boost=' || (r->'rows'->0->>'id');
  -- 6 short excerpts: a long chunk is cut to whole sentences around the words asked for; 'cut' says so
  r := public.pb_ai_kb_shelf_search('spoil pile how far back from the edge', 'TX', 1, array['spoil', 'pile', 'far', 'back', 'edge'], null, 300);
  x := r->'rows'->0;
  out := out || ' excerpt=' || length(x->>'text') || 'ch';
  ok := ok and x->>'id' = 'tc-tx-zz-2' and length(x->>'text') <= 300 and (x->>'cut')::boolean and x->>'text' like '%Spoil piles are kept at least 2 feet back from the edge of the trench.%' and right(x->>'text', 1) = '.';
  r := public.pb_ai_kb_shelf_search('spoil pile how far back from the edge', 'TX', 1, array['spoil', 'pile', 'far', 'back', 'edge'], null, 1800);
  ok := ok and r->'rows'->0->>'text' = long_tx and not (r->'rows'->0->>'cut')::boolean;
  -- 7 weights from Ask: the rare word decides the cover
  r := public.pb_ai_kb_shelf_search('x', 'TX', 5, array['paddle', 'trench'], null, 700, array[9, 1]::real[]);
  ok := ok and (select (e->>'cover')::numeric from jsonb_array_elements(r->'rows') e where e->>'id' = 'tc-tx-zz-1') = 0.9;
  -- 8 collections filter; k is capped; at most 2 per title
  r := public.pb_ai_kb_shelf_search('flagger paddle', 'TX', 50, array['flagger', 'paddle'], array['mutcd']);
  select count(*) into n from jsonb_array_elements(r->'rows') e where e->>'coll' <> 'mutcd';
  ok := ok and n = 0 and jsonb_array_length(r->'rows') = 2; out := out || ' coll=ok';
  -- 9 nothing typed can break it: quotes, operators, SQL, stop words only, empty, null, a state that is not one
  for x in select * from jsonb_array_elements('["\"unclosed quote", "a & | ! (b", "-paddle or :* <->", "''); drop table pb_ai.kb_shelf; --", "the and of", "", "   ", "%_\\\\", "paddle OR 1=1"]'::jsonb) loop
    r := public.pb_ai_kb_shelf_search(x #>> '{}', 'TX', 3);
    ok := ok and (r->>'ok')::boolean;
    r := public.pb_ai_kb_shelf_search(x #>> '{}', 'TX', 3, array[x #>> '{}', 'flagger paddle']);
    ok := ok and (r->>'ok')::boolean;
  end loop;
  ok := ok and (public.pb_ai_kb_shelf_search(null)->>'ok')::boolean and jsonb_array_length(public.pb_ai_kb_shelf_search('the and of', 'TX')->'rows') = 0
           and not exists (select 1 from jsonb_array_elements(public.pb_ai_kb_shelf_search('flagger paddle', 'TX''; --', 5)->'rows') e where e->>'state' <> 'US')
           and (select count(*) from pb_ai.kb_shelf where id like '%-zz-%') = 6;
  out := out || ' hostile=ok';
  -- 10 who can call it: the Ask function's role only; nobody reads the table directly
  ok := ok and has_function_privilege('service_role', procedure_sig, 'execute')
           and not has_function_privilege('anon', procedure_sig, 'execute') and not has_function_privilege('authenticated', procedure_sig, 'execute')
           and not has_function_privilege('public', procedure_sig, 'execute')
           and not has_table_privilege('anon', 'pb_ai.kb_shelf', 'select') and not has_table_privilege('authenticated', 'pb_ai.kb_shelf', 'select')
           and not has_table_privilege('service_role', 'pb_ai.kb_shelf', 'select, insert, update, delete')
           and not has_function_privilege('authenticated', 'pb_ai.kb_shelf_excerpt(text, tsquery[], integer)', 'execute')
           and (select p.prosecdef and p.proconfig @> array['search_path=""'] from pg_catalog.pg_proc p where p.oid = procedure_sig::regprocedure)
           and (select c.relrowsecurity from pg_catalog.pg_class c where c.oid = 'pb_ai.kb_shelf'::regclass)
           and not exists (select 1 from pg_catalog.pg_policies where schemaname = 'pb_ai' and tablename = 'kb_shelf');
  out := out || ' grants=' || case when has_function_privilege('service_role', procedure_sig, 'execute') and not has_function_privilege('authenticated', procedure_sig, 'execute') then 'service_role_only' else 'WRONG' end;
  -- as the Ask function's role: the function works, the table does not
  begin
    set local role service_role;
    r := public.pb_ai_kb_shelf_search('flagger paddle', 'TX', 2);
    ok := ok and jsonb_array_length(r->'rows') = 2;
    begin perform 1 from pb_ai.kb_shelf limit 1; ok := false; out := out || ' table=READABLE'; exception when insufficient_privilege then out := out || ' table=closed'; end;
    reset role;
  exception when others then reset role; out := out || ' role_test=' || sqlerrm; ok := false; end;
  begin
    set local role authenticated;
    begin r := public.pb_ai_kb_shelf_search('flagger paddle', 'TX', 2); ok := false; out := out || ' user=CAN_CALL'; exception when insufficient_privilege then out := out || ' user=refused'; end;
    reset role;
  exception when others then reset role; out := out || ' role_test2=' || sqlerrm; ok := false; end;
  -- 11 speed on the rows that are there
  t0 := clock_timestamp();
  for n in 1..20 loop r := public.pb_ai_kb_shelf_search('How wide does the flagger paddle have to be?', 'TX', 3, array['wide width', 'flagger', 'paddle']); end loop;
  ms := round((extract(epoch from clock_timestamp() - t0) * 1000 / 20)::numeric, 1);
  out := out || ' ms=' || ms || ' shelf_rows=' || (select count(*) from pb_ai.kb_shelf);
  raise exception 'RESULT: % %', case when ok then 'PASS' else 'FAIL' end, out;
end $t$;

rollback;
